use crate::{ast::{Expr,Op,Stmt,Value},lexer::{Span,Token,TokenKind}};
#[derive(Debug,Clone,PartialEq)] pub struct ParseError{pub message:String,pub span:Span}
pub struct Parser{tokens:Vec<Token>,pos:usize}
impl Parser{pub fn new(tokens:Vec<Token>)->Self{Self{tokens,pos:0}}fn peek(&self)->&TokenKind{&self.tokens[self.pos].kind}fn span(&self)->Span{self.tokens[self.pos].span}fn advance(&mut self)->Token{let t=self.tokens[self.pos].clone();self.pos+=1;t}fn eat(&mut self,k:&TokenKind)->bool{if self.peek()==k{self.advance();true}else{false}}fn expect(&mut self,k:&TokenKind)->Result<Token,ParseError>{if self.peek()==k{Ok(self.advance())}else{Err(ParseError{message:format!("expected {:?}, found {:?}",k,self.peek()),span:self.span()})}}fn skip(&mut self){while self.eat(&TokenKind::Newline){}}
pub fn parse_program(&mut self)->Result<Stmt,Vec<ParseError>>{let mut es=Vec::new();self.skip();if !self.eat(&TokenKind::BeginProgram){es.push(ParseError{message:"program must start with `begin`".into(),span:self.span()})}self.skip();let mut body=Vec::new();while !matches!(self.peek(),TokenKind::End|TokenKind::Eof){match self.statement(){Ok(s)=>body.push(s),Err(e)=>{es.push(e);while !matches!(self.peek(),TokenKind::Newline|TokenKind::End|TokenKind::Eof){self.advance();}self.skip()}}self.skip()}if !self.eat(&TokenKind::End){es.push(ParseError{message:"expected `end`".into(),span:self.span()})}if es.is_empty(){Ok(Stmt::Block(body))}else{Err(es)}}
fn statement(&mut self)->Result<Stmt,ParseError>{match self.peek(){TokenKind::Let=>{let sp=self.advance().span;let name=match self.advance().kind{TokenKind::Identifier(n)=>n,_=>return Err(ParseError{message:"expected variable name after `let`".into(),span:self.span()})};self.expect(&TokenKind::Be)?;Ok(Stmt::Let{name,value:self.expression(0)?,span:sp})},TokenKind::Print=>{self.advance();Ok(Stmt::Print(self.expression(0)?))},TokenKind::If=>self.conditional(),TokenKind::Repeat=>{let sp=self.advance().span;let iterations=self.expression(0)?;self.expect(&TokenKind::Times)?;self.skip();let mut body=Vec::new();while !matches!(self.peek(),TokenKind::End|TokenKind::Eof){body.push(self.statement()?);self.skip()}self.expect(&TokenKind::End)?;Ok(Stmt::RepeatLoop{iterations,body,span:sp})},TokenKind::Create=>{let sp=self.advance().span;self.expect(&TokenKind::Window)?;if let TokenKind::Identifier(x)=self.peek(){if x=="with"{self.advance();}}self.expect(&TokenKind::Title)?;let title=match self.advance().kind{TokenKind::StringLiteral(s)=>s,_=>return Err(ParseError{message:"window title must be a string".into(),span:self.span()})};self.expect(&TokenKind::And)?;self.expect(&TokenKind::Width)?;let width=self.expression(0)?;self.expect(&TokenKind::And)?;self.expect(&TokenKind::Height)?;let height=self.expression(0)?;Ok(Stmt::CreateWindow{title,width,height,span:sp})},_=>Err(ParseError{message:format!("unexpected token {:?} in statement",self.peek()),span:self.span()})}}
fn conditional(&mut self)->Result<Stmt,ParseError>{let sp=self.advance().span;let condition=self.expression(0)?;self.expect(&TokenKind::Then)?;self.skip();let mut yes=Vec::new();while !matches!(self.peek(),TokenKind::Otherwise|TokenKind::End|TokenKind::Eof){yes.push(self.statement()?);self.skip()}let no=if self.eat(&TokenKind::Otherwise){self.skip();let mut v=Vec::new();while !matches!(self.peek(),TokenKind::End|TokenKind::Eof){v.push(self.statement()?);self.skip()}Some(v)}else{None};self.expect(&TokenKind::End)?;Ok(Stmt::Conditional{condition,then_branch:yes,otherwise_branch:no,span:sp})}
fn expression(&mut self,min:u8)->Result<Expr,ParseError>{let mut left=match self.advance(){Token{kind:TokenKind::Number(n),span}=>Expr::Literal(Value::Number(n),span),Token{kind:TokenKind::StringLiteral(s),span}=>Expr::Literal(Value::String(s),span),Token{kind:TokenKind::True,span}=>Expr::Literal(Value::Boolean(true),span),Token{kind:TokenKind::False,span}=>Expr::Literal(Value::Boolean(false),span),Token{kind:TokenKind::Identifier(s),span}=>Expr::Variable(s,span),Token{kind:TokenKind::Minus,span}=>Expr::Unary{op:Op::Neg,expr:Box::new(self.expression(7)?),span},Token{kind:TokenKind::LeftParen,..}=>{let e=self.expression(0)?;self.expect(&TokenKind::RightParen)?;e},t=>return Err(ParseError{message:format!("expected expression, found {:?}",t.kind),span:t.span})};loop{let(op,l,r)=match self.peek(){TokenKind::Or=>(Op::Or,1,2),TokenKind::And=>(Op::And,3,4),TokenKind::EqualEqual=>(Op::Eq,5,6),TokenKind::Plus=>(Op::Add,7,8),TokenKind::Minus=>(Op::Sub,7,8),TokenKind::Star=>(Op::Mul,9,10),TokenKind::Slash=>(Op::Div,9,10),_=>break};if l<min{break}self.advance();let right=self.expression(r)?;let span=left.span();left=Expr::Binary{left:Box::new(left),op,right:Box::new(right),span}}Ok(left)}}
